# Define helper
def color_regions(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    regions = {}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                val = grid[r][c]
                region = {'val': val, 'cells': [], 'rmin': r, 'rmax': r, 'cmin': c, 'cmax': c}
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    region['cells'].append((cr, cc))
                    region['rmin'] = min(region['rmin'], cr)
                    region['rmax'] = max(region['rmax'], cr)
                    region['cmin'] = min(region['cmin'], cc)
                    region['cmax'] = max(region['cmax'], cc)

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] == val:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.setdefault(val, []).append(region)

    return regions

def find_hollow_frames(grid):
    """Find hollow frames - rectangular borders that enclose an area"""
    h, w = len(grid), len(grid[0])
    frames = []

    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] == 0:
                continue
            val = grid[r1][c1]

            # Try extending the rectangle
            for r2 in range(r1+2, h):
                for c2 in range(c1+2, w):
                    # Check if this forms a valid hollow frame
                    is_frame = True

                    # Check all four sides
                    for c in range(c1, c2+1):
                        if grid[r1][c] != val or grid[r2][c] != val:
                            is_frame = False
                            break
                    if not is_frame:
                        continue

                    for r in range(r1+1, r2):
                        if grid[r][c1] != val or grid[r][c2] != val:
                            is_frame = False
                            break

                    if not is_frame:
                        continue

                    # Check interior is hollow (contains bg or other non-frame colors)
                    interior_cells = []
                    for r in range(r1+1, r2):
                        for c in range(c1+1, c2):
                            interior_cells.append((r, c, grid[r][c]))

                    if not interior_cells:
                        continue

                    # This is a frame if it has interior
                    frames.append({
                        'val': val, 'r1': r1, 'r2': r2, 'c1': c1, 'c2': c2,
                        'interior': interior_cells
                    })

    return frames

